// TestIntegrationDatabaseMigrations is the deterministic bootstrap boundary
// for the shared disposable database used by the release integration suite.
// The workflows run it explicitly before package tests; keeping the check in
// Go also verifies every embedded migration and the preserved SmartSQL schema.
func TestIntegrationDatabaseMigrations(t *testing.T) {
	dsn := strings.TrimSpace(os.Getenv("POSTGRES_DSN"))
	if dsn == "" {
		t.Skip("POSTGRES_DSN is required for integration migration bootstrap")
	}
	ctx, cancel := context.WithTimeout(t.Context(), time.Minute)
	defer cancel()
	pool, err := pgxpool.New(ctx, dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	if err := pool.Ping(ctx); err != nil {
		t.Fatal(err)
	}
	if err := store.RunMigrations(ctx, pool, migrations.FS, "."); err != nil {
		t.Fatal(err)
	}
	report, err := legacyschema.NewInspector(pool).Inspect(ctx, "public")
	if err != nil {
		t.Fatal(err)
	}
	if !report.Compatible {
		t.Fatalf("migrated SmartSQL schema is incompatible: %#v", report)
	}
}

